 */
function stripUnparseable(endpoint: string): string {
  let text = endpoint.trim();
  const cut = [text.indexOf("?"), text.indexOf("#")].filter((i) => i >= 0);
  if (cut.length) text = text.slice(0, Math.min(...cut));
